from abc import ABC, abstractmethod

from ..entity import AggregateRoot


class IWriteRepository[TAggregate: AggregateRoot, TId](ABC):
    """Port for writing aggregates (Domain / Command side)."""

    @abstractmethod
    async def get_by_id(self, aggregate_id: TId) -> TAggregate:
        """Load an aggregate to execute a command. Raises NotFoundError if missing."""
        ...

    @abstractmethod
    async def save(self, aggregate: TAggregate) -> None:
        """Persist new domain events generated by the aggregate."""
        ...

    @abstractmethod
    async def exists(self, aggregate_id: TId) -> bool:
        ...

    @abstractmethod
    async def delete(self, aggregate_id: TId) -> None:
        """Delete an aggregate by id. No-op if it does not exist."""
        ...